import { useState, useRef, useCallback } from "react";

// Reference photo, embedded so this works standalone.
const REF_IMAGE = "data:image/png;base64,";

// Each point gets a stable id. "anchor" points are real path vertices (M/L endpoints,
// and the terminal point of a C curve). "c1"/"c2" are bezier control handles — they pull
// the curve but are never on the curve itself.
function makeId(seg, role) {
  return `${seg}-${role}`;
}

const INITIAL_SEGMENTS = [
  { cmd: "M", anchor: { x: 135.5, y: 469.5 } },
  { cmd: "L", anchor: { x: 180.5, y: 379.5 } },
  { cmd: "C", c1: { x: 105.5, y: 282 }, c2: { x: 90.5, y: 147 }, anchor: { x: 150.5, y: 57 } },
  { cmd: "C", c1: { x: 180.5, y: 27 }, c2: { x: 203, y: 19.5 }, anchor: { x: 233, y: 19.5 } },
  { cmd: "L", anchor: { x: 578, y: 19.5 } },
  { cmd: "C", c1: { x: 653, y: 19.5 }, c2: { x: 698, y: 72 }, anchor: { x: 720.5, y: 124.5 } },
  { cmd: "C", c1: { x: 698, y: 162 }, c2: { x: 653, y: 162 }, anchor: { x: 510.5, y: 147 } },
  { cmd: "L", anchor: { x: 278, y: 147 } },
  { cmd: "C", c1: { x: 210.5, y: 147 }, c2: { x: 165.5, y: 184.5 }, anchor: { x: 150.5, y: 257.5 } },
  { cmd: "C", c1: { x: 128, y: 327 }, c2: { x: 113, y: 357 }, anchor: { x: 150.5, y: 417 } },
  { cmd: "L", anchor: { x: 135.5, y: 469.5 } },
  { cmd: "Z" },
];

// Flatten the segment list into an { id: {x,y} } lookup, and a parallel list of
// { id, segIndex, role } descriptors so dragging can write straight back into segments.
function buildPointIndex(segments) {
  const points = {};
  const descriptors = [];
  segments.forEach((seg, i) => {
    if (seg.cmd === "Z") return;
    if (seg.c1) {
      const id = makeId(i, "c1");
      points[id] = seg.c1;
      descriptors.push({ id, segIndex: i, role: "c1" });
    }
    if (seg.c2) {
      const id = makeId(i, "c2");
      points[id] = seg.c2;
      descriptors.push({ id, segIndex: i, role: "c2" });
    }
    if (seg.anchor) {
      const id = makeId(i, "anchor");
      points[id] = seg.anchor;
      descriptors.push({ id, segIndex: i, role: "anchor" });
    }
  });
  return { points, descriptors };
}

function midpoint(a, b) {
  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
}

// De Casteljau split of a cubic bezier at t = 0.5: returns two cubic beziers that
// together retrace the original curve exactly, plus the point where they meet.
function splitCubic(p0, c1, c2, p3) {
  const e = midpoint(p0, c1);
  const f = midpoint(c1, c2);
  const g = midpoint(c2, p3);
  const h = midpoint(e, f);
  const j = midpoint(f, g);
  const k = midpoint(h, j);
  return {
    first: { c1: e, c2: h, anchor: k },
    second: { c1: j, c2: g, anchor: p3 },
    mid: k,
  };
}

function segmentsToPath(segments) {
  return segments
    .map((seg) => {
      if (seg.cmd === "M") return `M ${seg.anchor.x.toFixed(1)},${seg.anchor.y.toFixed(1)}`;
      if (seg.cmd === "L") return `L ${seg.anchor.x.toFixed(1)},${seg.anchor.y.toFixed(1)}`;
      if (seg.cmd === "C")
        return `C ${seg.c1.x.toFixed(1)},${seg.c1.y.toFixed(1)} ${seg.c2.x.toFixed(1)},${seg.c2.y.toFixed(1)} ${seg.anchor.x.toFixed(1)},${seg.anchor.y.toFixed(1)}`;
      return "Z";
    })
    .join(" ");
}

// Normalizes the current point cloud into a clean 0-100 viewBox path, the same
// convention the original logo file used, so it can be pasted straight back in.
function segmentsToNormalizedPath(segments) {
  const xs = [];
  const ys = [];
  segments.forEach((seg) => {
    if (seg.anchor) {
      xs.push(seg.anchor.x);
      ys.push(seg.anchor.y);
    }
  });
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);
  const span = Math.max(maxX - minX, maxY - minY) || 1;
  const norm = (v, min) => ((v - min) / span) * 100;
  const scaled = segments.map((seg) => {
    if (seg.cmd === "Z") return seg;
    const out = { cmd: seg.cmd };
    if (seg.c1) out.c1 = { x: norm(seg.c1.x, minX), y: norm(seg.c1.y, minY) };
    if (seg.c2) out.c2 = { x: norm(seg.c2.x, minX), y: norm(seg.c2.y, minY) };
    if (seg.anchor) out.anchor = { x: norm(seg.anchor.x, minX), y: norm(seg.anchor.y, minY) };
    return out;
  });
  return segmentsToPath(scaled);
}

export default function HookEditor() {
  const [segments, setSegments] = useState(INITIAL_SEGMENTS);
  const [refOpacity, setRefOpacity] = useState(0.5);
  const [showRef, setShowRef] = useState(true);
  const [showHandles, setShowHandles] = useState(true);
  const [fillOpacity, setFillOpacity] = useState(0.55);
  const [copied, setCopied] = useState(false);
  const [dragId, setDragId] = useState(null);
  const svgRef = useRef(null);

  const { points, descriptors } = buildPointIndex(segments);
  const pathD = segmentsToPath(segments);

  const toSvgPoint = useCallback((clientX, clientY) => {
    const svg = svgRef.current;
    const pt = svg.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    const ctm = svg.getScreenCTM();
    const inv = ctm.inverse();
    const transformed = pt.matrixTransform(inv);
    return { x: transformed.x, y: transformed.y };
  }, []);

  function updatePoint(id, x, y) {
    const desc = descriptors.find((d) => d.id === id);
    if (!desc) return;
    setSegments((prev) => {
      const next = prev.map((seg) => ({ ...seg }));
      next[desc.segIndex][desc.role] = { x, y };
      // Keep the closing "L back to start" anchor glued to the opening M point.
      if (desc.segIndex === 0 && desc.role === "anchor") {
        const last = next[next.length - 2];
        if (last && last.cmd === "L") last.anchor = { x, y };
      }
      return next;
    });
  }

  function handlePointerDown(id) {
    return (e) => {
      e.stopPropagation();
      setDragId(id);
    };
  }

  function handlePointerMove(e) {
    if (!dragId) return;
    const p = toSvgPoint(e.clientX, e.clientY);
    updatePoint(dragId, p.x, p.y);
  }

  function handlePointerUp() {
    setDragId(null);
  }

  function handleReset() {
    setSegments(INITIAL_SEGMENTS);
  }

  // Splits the segment at segIndex into two, adding a real anchor point at its
  // midpoint (the curve's actual t=0.5 point for C segments) without changing the shape.
  function insertPointAt(segIndex) {
    setSegments((prev) => {
      const next = prev.map((seg) => ({ ...seg }));
      const seg = next[segIndex];
      const prevAnchor = next[segIndex - 1].anchor;
      if (seg.cmd === "L") {
        const m = midpoint(prevAnchor, seg.anchor);
        next.splice(segIndex, 1, { cmd: "L", anchor: m }, { cmd: "L", anchor: seg.anchor });
      } else if (seg.cmd === "C") {
        const { first, second } = splitCubic(prevAnchor, seg.c1, seg.c2, seg.anchor);
        next.splice(
          segIndex,
          1,
          { cmd: "C", c1: first.c1, c2: first.c2, anchor: first.anchor },
          { cmd: "C", c1: second.c1, c2: second.c2, anchor: second.anchor }
        );
      }
      return next;
    });
  }

  // Removes an anchor point, collapsing its two flanking segments into one. Guards
  // against deleting the opening M or the closing point that mirrors it.
  function deletePointAt(segIndex) {
    if (segIndex <= 0 || segIndex >= segments.length - 2) return;
    setSegments((prev) => {
      const next = prev.map((seg) => ({ ...seg }));
      next.splice(segIndex, 1);
      return next;
    });
  }

  // Midpoint markers shown on each segment so a point can be added there — for C
  // segments this is the true point on the curve, not the straight-line midpoint.
  const insertMarkers = segments
    .map((seg, i) => {
      if (i === 0 || seg.cmd === "Z") return null;
      const prevAnchor = segments[i - 1].anchor;
      if (seg.cmd === "L") return { segIndex: i, pos: midpoint(prevAnchor, seg.anchor) };
      if (seg.cmd === "C") return { segIndex: i, pos: splitCubic(prevAnchor, seg.c1, seg.c2, seg.anchor).mid };
      return null;
    })
    .filter(Boolean);

  async function handleCopy() {
    const normalized = segmentsToNormalizedPath(segments);
    try {
      await navigator.clipboard.writeText(normalized);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch (e) {
      // clipboard may be blocked in sandboxed previews; text is visible below regardless
    }
  }

  const normalizedPreview = segmentsToNormalizedPath(segments);

  return (
    <div
      className="min-h-screen w-full flex items-center justify-center p-6"
      style={{ background: "#0B1622" }}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerLeave={handlePointerUp}
    >
      <div className="w-full max-w-5xl flex flex-col gap-5">
        <div>
          <h1 className="text-white/90 text-lg font-medium mb-1">Top hook, alone</h1>
          <p className="text-white/50 text-sm leading-relaxed max-w-xl">
            Drag the white dots to move the ribbon's actual path. Drag the small
            orange dots to bend the curve between two points. Click a green "+" to
            add a new point at that spot on the curve — useful anywhere the shape
            needs more control than a single bezier gives you. Double-click a white
            dot to remove it. The reference photo sits underneath so you can trace it
            directly.
          </p>
        </div>

        <div className="flex flex-wrap gap-4 items-center text-white/60 text-xs">
          <label className="flex items-center gap-2">
            <input type="checkbox" checked={showRef} onChange={(e) => setShowRef(e.target.checked)} />
            Show reference
          </label>
          <label className="flex items-center gap-2">
            Reference opacity
            <input
              type="range"
              min={0}
              max={1}
              step={0.05}
              value={refOpacity}
              onChange={(e) => setRefOpacity(Number(e.target.value))}
              className="accent-white/80 w-28"
            />
          </label>
          <label className="flex items-center gap-2">
            <input type="checkbox" checked={showHandles} onChange={(e) => setShowHandles(e.target.checked)} />
            Show curve handles
          </label>
          <label className="flex items-center gap-2">
            Shape fill
            <input
              type="range"
              min={0}
              max={1}
              step={0.05}
              value={fillOpacity}
              onChange={(e) => setFillOpacity(Number(e.target.value))}
              className="accent-white/80 w-28"
            />
          </label>
          <button
            onClick={handleReset}
            className="px-3 py-1.5 rounded-full border border-white/15 hover:text-white hover:border-white/30 transition-colors"
          >
            Reset points
          </button>
          <button
            onClick={handleCopy}
            className="px-3 py-1.5 rounded-full border border-white/15 hover:text-white hover:border-white/30 transition-colors"
          >
            {copied ? "Copied ✓" : "Copy normalized path"}
          </button>
        </div>

        <div
          className="rounded-2xl overflow-hidden border border-white/10"
          style={{ background: "#05080D", touchAction: "none" }}
        >
          <svg
            ref={svgRef}
            viewBox="0 0 841 547"
            className="w-full h-auto block select-none"
            style={{ cursor: dragId ? "grabbing" : "default" }}
          >
            <defs>
              <linearGradient id="hookGradient" x1="0" y1="0" x2="841" y2="547" gradientUnits="userSpaceOnUse">
                <stop offset="0%" stopColor="#3FC6F6" />
                <stop offset="100%" stopColor="#1257AE" />
              </linearGradient>
            </defs>

            {showRef && (
              <image
                href={REF_IMAGE}
                x="0"
                y="0"
                width="841"
                height="547"
                opacity={refOpacity}
                preserveAspectRatio="xMidYMid meet"
              />
            )}

            <path
              d={pathD}
              fill="url(#hookGradient)"
              fillOpacity={fillOpacity}
              stroke="#EAF6FF"
              strokeWidth={1.5}
            />

            {showHandles &&
              segments.map((seg, i) => {
                if (seg.cmd !== "C") return null;
                const prevAnchor = segments[i - 1]?.anchor;
                return (
                  <g key={`handle-lines-${i}`}>
                    {prevAnchor && (
                      <line
                        x1={prevAnchor.x}
                        y1={prevAnchor.y}
                        x2={seg.c1.x}
                        y2={seg.c1.y}
                        stroke="#FFB020"
                        strokeWidth={1}
                        strokeDasharray="3 3"
                        opacity={0.7}
                      />
                    )}
                    <line
                      x1={seg.anchor.x}
                      y1={seg.anchor.y}
                      x2={seg.c2.x}
                      y2={seg.c2.y}
                      stroke="#FFB020"
                      strokeWidth={1}
                      strokeDasharray="3 3"
                      opacity={0.7}
                    />
                  </g>
                );
              })}

            {insertMarkers.map((m) => (
              <g
                key={`add-${m.segIndex}`}
                style={{ cursor: "copy" }}
                onPointerDown={(e) => e.stopPropagation()}
                onClick={(e) => {
                  e.stopPropagation();
                  insertPointAt(m.segIndex);
                }}
              >
                <circle cx={m.pos.x} cy={m.pos.y} r={7} fill="#0B1622" stroke="#37D67A" strokeWidth={1.5} opacity={0.85} />
                <line x1={m.pos.x - 3.5} y1={m.pos.y} x2={m.pos.x + 3.5} y2={m.pos.y} stroke="#37D67A" strokeWidth={1.5} />
                <line x1={m.pos.x} y1={m.pos.y - 3.5} x2={m.pos.x} y2={m.pos.y + 3.5} stroke="#37D67A" strokeWidth={1.5} />
              </g>
            ))}

            {descriptors.map((d) => {
              const p = points[d.id];
              const isAnchor = d.role === "anchor";
              if (!showHandles && !isAnchor) return null;
              return (
                <circle
                  key={d.id}
                  cx={p.x}
                  cy={p.y}
                  r={isAnchor ? 8 : 5.5}
                  fill={isAnchor ? "#FFFFFF" : "#FFB020"}
                  fillOpacity={isAnchor ? 1 : 0.25}
                  stroke={isAnchor ? "#1257AE" : "#FFB020"}
                  strokeWidth={isAnchor ? 2 : 1.5}
                  style={{ cursor: "grab" }}
                  onPointerDown={handlePointerDown(d.id)}
                  onDoubleClick={(e) => {
                    if (!isAnchor) return;
                    e.stopPropagation();
                    deletePointAt(d.segIndex);
                  }}
                />
              );
            })}
          </svg>
        </div>

        <div>
          <div className="text-white/50 text-xs mb-2">Normalized path (0–100 viewBox, ready to paste as TOP_PATH)</div>
          <textarea
            readOnly
            value={normalizedPreview}
            className="w-full bg-black/30 border border-white/10 rounded-xl text-white/70 text-xs font-mono p-3 outline-none resize-none"
            rows={3}
            onClick={(e) => e.target.select()}
          />
        </div>
      </div>
    </div>
  );
}